+const TOOL_NAME = 'users_get_many';
+const MAX_IDS = 5;
+const ALLOWED = new Set(['user_ids']);
+
+export async function listTools() {
+  return [
+    {
+      name: TOOL_NAME,
+      description:
+        'Look up multiple users by id in a single batch. Returns one line per requested id in request order, marking missing users without failing the batch.',
+      inputSchema: {
+        type: 'object',
+        properties: {
+          user_ids: {
+            type: 'array',
+            items: { type: 'string' },
+            minItems: 1,
+            maxItems: MAX_IDS,
+            uniqueItems: true
+          }
+        },
+        required: ['user_ids'],
+        additionalProperties: false
+      }
+    }
+  ];
+}
+
+export async function callTool(name, args) {
+  if (name !== TOOL_NAME) {
+    throw new Error(`Unknown tool: ${name}`);
+  }
+  if (args === null || typeof args !== 'object' || Array.isArray(args)) {
+    throw new Error('Invalid arguments: expected an object');
+  }
+  const extra = Object.keys(args).filter((k) => !ALLOWED.has(k));
+  if (extra.length > 0) {
+    throw new Error(`Unexpected fields: ${extra.join(', ')}`);
+  }
+  if (!('user_ids' in args)) {
+    throw new Error('user_ids is required');
+  }
+  const { user_ids } = args;
+  if (!Array.isArray(user_ids)) {
+    throw new Error('user_ids must be an array');
+  }
+  if (user_ids.length === 0) {
+    throw new Error('user_ids must not be empty');
+  }
+  if (user_ids.length > MAX_IDS) {
+    throw new Error(`user_ids must have at most ${MAX_IDS} entries`);
+  }
+  const seen = new Set();
+  for (const id of user_ids) {
+    if (typeof id !== 'string') {
+      throw new Error('user_ids must contain only strings');
+    }
+    if (seen.has(id)) {
+      throw new Error(`Duplicate user id: ${id}`);
+    }
+    seen.add(id);
+  }
+  const lines = user_ids.map((id) => {
+    const user = users[id];
+    return user ? `${id}: ${user.name}` : `${id}: not found`;
+  });
